var n = 0
for uid in GameState.state.units:
	var u = GameState.state.units[uid]
	if int(u.get("owner", 0)) != 2:
		continue
	if not u.has("flags"):
		u["flags"] = {}
	u["flags"]["was_eligible_to_fight"] = true
	n += 1
return n

var p = tree.root.get_node("Main/HUD_Right/VBoxContainer/FightScrollContainer/FightPanel/ConsolidationStepPanel")
var row = null
for c in p.get_node("UnitList").get_children():
	if c is Button:
		row = c
		break
if row == null:
	return "no rows"
return p.get_node("StepInstructions").get_theme_color("font_color") != row.get_theme_color("font_color")

var ul = tree.root.get_node("Main/HUD_Right/VBoxContainer/FightScrollContainer/FightPanel/ConsolidationStepPanel/UnitList")
var row = null
for c in ul.get_children():
	if c is Button:
		row = c
		break
if row == null:
	return "no rows"
if not row.has_theme_stylebox_override("normal"):
	return "no stylebox override"
return row.get_theme_stylebox("normal").border_width_left

var ul = tree.root.get_node("Main/HUD_Right/VBoxContainer/FightScrollContainer/FightPanel/ConsolidationStepPanel/UnitList")
var n = 0
for c in ul.get_children():
	if c is Button:
		n += 1
return n

var ul = tree.root.get_node("Main/HUD_Right/VBoxContainer/FightScrollContainer/FightPanel/ConsolidationStepPanel/UnitList")
var shown = 0
var total = 0
var off_topic = 0
for c in ul.get_children():
	if not (c is Button):
		continue
	total += 1
	if c.visible:
		shown += 1
		if c.text.to_lower().find("boy") == -1:
			off_topic += 1
return "%d/%d off=%d" % [shown, total, off_topic]

var ul = tree.root.get_node("Main/HUD_Right/VBoxContainer/FightScrollContainer/FightPanel/ConsolidationStepPanel/UnitList")
var shown = 0
var total = 0
var off_topic = 0
for c in ul.get_children():
	if not (c is Button):
		continue
	total += 1
	if c.visible:
		shown += 1
		if c.text.to_lower().find("boy") == -1:
			off_topic += 1
return shown > 0 and shown < total and off_topic == 0

var ul = tree.root.get_node("Main/HUD_Right/VBoxContainer/FightScrollContainer/FightPanel/ConsolidationStepPanel/UnitList")
var hidden = 0
for c in ul.get_children():
	if c is Button and not c.visible:
		hidden += 1
return hidden
